function NoticeManager({profile,setMsg}){const {t}=useTranslation();const [rows,setRows]=useState([]),[title,setTitle]=useState(""),[content,setContent]=useState("");const load=()=>sb.from("notices").select("*").order("created_at",{ascending:false}).then(({data,error})=>{setRows(data||[]);if(error)setMsg(error.message)});useEffect(()=>{load()},[]);async function add(){if(!title.trim()||!content.trim())return setMsg(t("notices.required"));const {error}=await sb.from("notices").insert({title:title.trim(),content:content.trim(),created_by:profile.id});if(error)return setMsg(error.message);setTitle("");setContent("");setMsg(t("notices.published"));load()}async function remove(id){if(!confirm(t("notices.deleteConfirm")))return;const {error}=await sb.from("notices").delete().eq("id",id);setMsg(error?.message||t("notices.deleted"));if(!error)load()}return <div className="dashboard-card manager-form"><p className="section-label">{t("notices.label")}</p><h1>{t("notices.title")}</h1><div className="manager-fields"><input value={title} onChange={e=>setTitle(e.target.value)} placeholder={t("notices.titlePlaceholder")}/><textarea value={content} onChange={e=>setContent(e.target.value)} placeholder={t("notices.contentPlaceholder")}/></div><button className="gold-button" onClick={add}>{t("notices.publish")}</button><div className="manager-list">{rows.map(x=><article key={x.id}><div><b>{x.title}</b><p>{x.content}</p></div><button onClick={()=>remove(x.id)}>{t("notices.delete")}</button></article>)}</div></div>}
function StudentReview({profile,setMsg}){const {t}=useTranslation();const [review,setReview]=useState(""),[rating,setRating]=useState(5),[rows,setRows]=useState([]);const load=()=>sb.from("student_reviews").select("*").eq("student_id",profile.id).order("created_at",{ascending:false}).then(({data})=>setRows(data||[]));useEffect(()=>{load()},[profile.id]);async function submit(){if(review.trim().length<5)return setMsg(t("reviews.longer"));const {error}=await sb.from("student_reviews").insert({student_id:profile.id,review:review.trim(),rating});if(error)return setMsg(error.message);setReview("");setMsg(t("reviews.submitted"));load()}return <div className="dashboard-card"><p className="section-label">{t("reviews.yourVoice")}</p><h1>{t("reviews.myReview")}</h1><div className="manager-fields"><select value={rating} onChange={e=>setRating(Number(e.target.value))}><option value="5">{`5 ${t("reviews.stars")}`}</option><option value="4">{`4 ${t("reviews.stars")}`}</option><option value="3">{`3 ${t("reviews.stars")}`}</option><option value="2">{`2 ${t("reviews.stars")}`}</option><option value="1">{`1 ${t("reviews.star")}`}</option></select><textarea value={review} onChange={e=>setReview(e.target.value)} placeholder={t("reviews.sharePlaceholder")}/></div><button className="gold-button" onClick={submit}>{t("reviews.submit")}</button><div className="manager-list">{rows.map(x=><article key={x.id}><div><b>{"★".repeat(x.rating)}</b><p>{x.review}</p></div><small>{x.approved?t("reviews.published"):t("reviews.pending")}</small></article>)}</div></div>}
function ReviewModeration({setMsg}){const {t}=useTranslation();const [rows,setRows]=useState([]),[busy,setBusy]=useState(false);const load=()=>sb.from("student_reviews").select("*,profiles!student_reviews_student_id_fkey(full_name,avatar_url)").order("created_at",{ascending:false}).then(({data})=>setRows(data||[]));useEffect(()=>{load()},[]);async function approve(id,value){setBusy(true);const {error}=await sb.from("student_reviews").update({approved:value,updated_at:new Date().toISOString()}).eq("id",id);setBusy(false);setMsg(error?.message||(value?t("reviews.approved"):t("reviews.hidden")));if(!error)load()}async function remove(id){if(!confirm(t("reviews.deleteConfirm")))return;setBusy(true);const {error}=await sb.from("student_reviews").delete().eq("id",id);setBusy(false);setMsg(error?.message||t("reviews.deleted"));if(!error)load()}return <div className="dashboard-card review-moderation"><p className="section-label">{t("reviews.communityVoices")}</p><h1>{t("reviews.studentReviews")}</h1><p>{t("reviews.moderationInfo")}</p><div className="review-admin-list">{rows.map(r=><article key={r.id}><ProfilePhoto url={r.profiles?.avatar_url} name={r.profiles?.full_name} size={44}/><div className="review-admin-copy"><b>{r.profiles?.full_name||t("reviews.student")}</b><div className="review-stars">{"★".repeat(r.rating)}{"☆".repeat(5-r.rating)}</div><p>{r.review}</p><small>{r.approved?t("reviews.published"):t("reviews.pending")}</small></div><div className="review-admin-actions"><button disabled={busy} onClick={()=>approve(r.id,!r.approved)}>{r.approved?t("reviews.hide"):t("reviews.approve")}</button><button disabled={busy} onClick={()=>remove(r.id)}>{t("reviews.delete")}</button></div></article>)}</div></div>}
function GalleryManager({profile,setMsg}){const {t}=useTranslation();const [title,setTitle]=useState("");const [file,setFile]=useState(null);const [rows,setRows]=useState([]);const [busy,setBusy]=useState(false);const load=()=>sb.from("gallery_items").select("id,title,image_url,approved,created_at").order("created_at",{ascending:false}).then(({data})=>setRows(data||[]));useEffect(()=>{load()},[]);async function upload(){if(!file){setMsg(t("gallery.selectImage"));return}if(!file.type.startsWith("image/")){setMsg(t("gallery.imageOnly"));return}if(file.size>10*1024*1024){setMsg(t("gallery.sizeLimit"));return}setBusy(true);try{const ext=(file.name.split(".").pop()||"jpg").toLowerCase().replace(/[^a-z0-9]/g,"")||"jpg";const path=`${profile.id}/${Date.now()}.${ext}`;const {error:upErr}=await sb.storage.from(GALLERY_BUCKET).upload(path,file,{contentType:file.type,cacheControl:"3600"});if(upErr)throw upErr;const {data}=sb.storage.from(GALLERY_BUCKET).getPublicUrl(path);const {error:dbErr}=await sb.from("gallery_items").insert({title:title.trim()||null,image_url:data.publicUrl,uploaded_by:profile.id,approved:false});if(dbErr)throw dbErr;setTitle("");setFile(null);setMsg(t("gallery.uploaded"));load()}catch(err){setMsg(err?.message||t("gallery.uploadFailed"))}finally{setBusy(false)}}async function toggle(id,value){const {error}=await sb.from("gallery_items").update({approved:value}).eq("id",id);setMsg(error?.message||(value?t("gallery.publishedMsg"):t("gallery.hiddenMsg")));if(!error)load()}async function remove(id,url){if(!confirm(t("gallery.deleteConfirm")))return;const path=(url||"").split(`/storage/v1/object/public/${GALLERY_BUCKET}/`)[1];if(path)await sb.storage.from(GALLERY_BUCKET).remove([path]);const {error}=await sb.from("gallery_items").delete().eq("id",id);setMsg(error?.message||t("gallery.deleted"));if(!error)load()}return <div className="dashboard-card gallery-manager"><p className="section-label">{t("gallery.label")}</p><h1>{t("gallery.title")}</h1><p>{t("gallery.description")}</p><div className="gallery-upload-form"><input value={title} onChange={e=>setTitle(e.target.value)} placeholder={t("gallery.titlePlaceholder")}/><label className="gallery-file-label">{file?file.name:t("gallery.choose")}<input type="file" accept="image/*" onChange={e=>setFile(e.target.files?.[0]||null)}/></label><button className="gold-button" disabled={busy} onClick={upload}>{busy?t("gallery.uploading"):t("gallery.upload")}</button></div><div className="gallery-admin-grid">{rows.map(g=><article key={g.id}><img src={g.image_url} alt={g.title||t("gallery.gallery")}/><div><b>{g.title||t("gallery.untitled")}</b><small>{g.approved?t("gallery.published"):t("gallery.draft")}</small></div><div className="gallery-admin-actions"><button onClick={()=>toggle(g.id,!g.approved)}>{g.approved?t("gallery.hide"):t("gallery.publish")}</button><button onClick={()=>remove(g.id,g.image_url)}>{t("reviews.delete")}</button></div></article>)}</div></div>}
function WebsiteEditor({settings,saveSettings,setMsg}){const {t}=useTranslation();const [form,setForm]=useState(settings);useEffect(()=>setForm(settings),[settings]);const update=(k,v)=>setForm(x=>({...x,[k]:v}));function save(){saveSettings(form);setMsg(t("websiteEditor.saved"))}return <div className="dashboard-card manager-form"><p className="section-label">{t("websiteEditor.label")}</p><h1>{t("websiteEditor.title")}</h1><div className="manager-fields"><input value={form.heroEyebrow||""} onChange={e=>update("heroEyebrow",e.target.value)} placeholder={t("websiteEditor.eyebrow")}/><input value={form.heroTitle||""} onChange={e=>update("heroTitle",e.target.value)} placeholder={t("websiteEditor.heroTitle")}/><textarea value={form.heroSubtitle||""} onChange={e=>update("heroSubtitle",e.target.value)} placeholder={t("websiteEditor.heroSubtitle")}/><textarea value={form.heroText||""} onChange={e=>update("heroText",e.target.value)} placeholder={t("websiteEditor.heroText")}/><input value={form.heroMusicImage||""} onChange={e=>update("heroMusicImage",e.target.value)} placeholder={t("websiteEditor.imageUrl")}/></div><button className="gold-button" onClick={save}>{t("websiteEditor.save")}</button></div>}
function Auth({mode,setPage,setMsg}){const {t}=useTranslation();const [email,setEmail]=useState("");const [password,setPassword]=useState("");const [name,setName]=useState("");const [busy,setBusy]=useState(false);async function submit(e){e.preventDefault();if(!email||!password||(mode==="register"&&!name.trim()))return setMsg("Please fill in all required fields.");if(password.length<6)return setMsg("Password must be at least 6 characters.");setBusy(true);try{if(mode==="register"){const {data,error}=await sb.auth.signUp({email,password,options:{data:{full_name:name.trim()}}});if(error)throw error;if(data.user&&!data.session)setMsg("Account created. Please check your email to confirm your account.");else setMsg("Account created successfully.");setPage("home")}else{const {error}=await sb.auth.signInWithPassword({email,password});if(error)throw error;setMsg("Welcome back!");setPage("dash")}}catch(err){setMsg(err?.message||"Authentication failed.")}finally{setBusy(false)}}return <div className="auth-page"><div className="auth-panel"><div className="auth-brand"><span>♫</span><h2>সুরছবি</h2><p>CREATIVE ARTS ACADEMY</p></div><form className="auth-form" onSubmit={submit}><h1>{mode==="register"?t("auth.createTitle"):t("auth.welcome")}</h1><p>{mode==="register"?t("auth.join"):t("auth.signInContinue")}</p>{mode==="register"&&<label>{t("auth.fullName")}<input value={name} onChange={e=>setName(e.target.value)} placeholder={t("auth.yourName")} autoComplete="name"/></label>}<label>{t("auth.email")}<input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com" autoComplete="email"/></label><label>{t("auth.password")}<input type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder={t("auth.minChars")} autoComplete={mode==="register"?"new-password":"current-password"}/></label><button className="gold-button" disabled={busy}>{busy?t("auth.pleaseWait"):mode==="register"?t("auth.createAccount"):t("auth.signIn")}</button>{mode==="login"?<><button type="button" className="auth-link" onClick={()=>setPage("forgot")}>{t("auth.forgot")}</button><p className="auth-switch">{t("auth.newTo")} <button type="button" onClick={()=>setPage("register")}>{t("auth.createAccount")}</button></p></>:<p className="auth-switch">{t("auth.already")} <button type="button" onClick={()=>setPage("login")}>{t("auth.signIn")}</button></p>}</form></div></div>}
function Forgot({setPage,setMsg}){const {t}=useTranslation();const [email,setEmail]=useState("");const [busy,setBusy]=useState(false);async function submit(e){e.preventDefault();if(!email)return setMsg("Please enter your email.");setBusy(true);try{const {error}=await sb.auth.resetPasswordForEmail(email,{redirectTo:window.location.origin});if(error)throw error;setMsg("Password reset link sent. Please check your email.");setPage("login")}catch(err){setMsg(err?.message||"Could not send reset email.")}finally{setBusy(false)}}return <div className="auth-page"><div className="auth-panel"><h1>{t("auth.forgotTitle")}</h1><form className="auth-form" onSubmit={submit}><label>{t("auth.email")}<input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com"/></label><button className="gold-button" disabled={busy}>{busy?t("auth.sending"):t("auth.sendReset")}</button><button type="button" className="auth-link" onClick={()=>setPage("login")}>{t("auth.backLogin")}</button></form></div></div>}
function Reset({setPage,setMsg}){const {t}=useTranslation();const [password,setPassword]=useState(""),[confirmPassword,setConfirmPassword]=useState(""),[busy,setBusy]=useState(false);async function submit(e){e.preventDefault();if(password.length<6)return setMsg("Password must be at least 6 characters.");if(password!==confirmPassword)return setMsg("Passwords do not match.");setBusy(true);try{const {error}=await sb.auth.updateUser({password});if(error)throw error;setMsg("Password updated successfully.");setPage("login")}catch(err){setMsg(err?.message||"Could not update password.")}finally{setBusy(false)}}return <div className="auth-page"><div className="auth-panel"><h1>{t("auth.resetTitle")}</h1><form className="auth-form" onSubmit={submit}><label>{t("auth.newPassword")}<input type="password" value={password} onChange={e=>setPassword(e.target.value)}/></label><label>{t("auth.confirmPassword")}<input type="password" value={confirmPassword} onChange={e=>setConfirmPassword(e.target.value)}/></label><button className="gold-button" disabled={busy}>{busy?t("auth.updating"):t("auth.updatePassword")}</button></form></div></div>}
function Footer({setPage}){const {t}=useTranslation();const mapUrl="https://maps.app.goo.gl/LBhogpWFV64igN4CA";return <footer className="modern-footer"><div className="footer-brand"><h2>{t("footer.academyName")}</h2><p>{t("footer.academyType")}</p><span>{t("footer.tagline")}</span></div><div><h4>{t("footer.explore")}</h4><p><button onClick={()=>setPage("courses")}>{t("footer.music")}</button></p><p><button onClick={()=>setPage("courses")}>{t("footer.dance")}</button></p><p><button onClick={()=>setPage("courses")}>{t("footer.photography")}</button></p></div><div><h4>{t("footer.academy")}</h4><p><button onClick={()=>setPage("about")}>{t("footer.about")}</button></p><p><button onClick={()=>setPage("faculty")}>{t("footer.faculty")}</button></p><p><button onClick={()=>setPage("courses")}>{t("footer.courses")}</button></p></div><div><h4>{t("footer.contactUs")}</h4><p><a href={mapUrl} target="_blank" rel="noreferrer">📍 {t("footer.address").split("\n").map((line,i)=><Fragment key={i}>{line}{i<2&&<br/>}</Fragment>)}</a></p><p><a href="tel:7908459814">📞 7908459814</a></p></div><div><h4>{t("footer.connect")}</h4><div className="socials"><span title="Facebook">f</span><span title="Instagram">◎</span><span title="YouTube">▶</span></div></div><div className="footer-bottom">{t("footer.rights")}</div></footer>}

